OK, I think I found a better way to fill a closed path with a hatch fill. I'll use the built-in function of Adobe Illustrator that does this task. I hope it works.

// This is the script I wrote

// Define a function that takes a closed path as an argument
function fillPathWithHatch(path) {
  // Check if the path is closed or not
  if (path.closed) {
    // Apply a hatch fill to the path
    path.hatchFill({
      "style": "mesh",
      "mesh": {
        "pattern": "lines",
        "angle": 45,
        "gap": 10
      },
      "color": path.fillColor
    });
  }
}

